		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 12, "<div>Pagaré Electrónico sobre <a href=\"https://api.blockchainfue.com/doc/api\">BlockchainFUE</a> — libro mayor electrónico no cualificado (art. 3.52 eIDAS2).</div><div style=\"margin-top:6px\"><a href=\"https://www.baeslegalcripto.eu/legalcripto/\">LegalCripto by BAES</a></div></footer><script>\n\t\t// The nav is rendered server-side from the authenticated user, so it is\n\t\t// consistent across every page (including the public verification page).\n\t\tfunction doLogout() {\n\t\t\tclearActiveKey();\n\t\t\tfetch('/api/auth/logout', { method: 'POST', credentials: 'same-origin' })\n\t\t\t\t.then(function() { window.location.href = '/login'; })\n\t\t\t\t.catch(function() { window.location.href = '/login'; });\n\t\t}\n\n\t\t// ===== Active signing key (kept in sessionStorage until logout / tab close) =====\n\t\tvar ACTIVE_KEY_STORE = 'pagare_active_key';\n\t\twindow.getActiveKey = function() {\n\t\t\ttry { return JSON.parse(sessionStorage.getItem(ACTIVE_KEY_STORE) || 'null'); } catch (e) { return null; }\n\t\t};\n\t\twindow.setActiveKey = function(k) {\n\t\t\tif (!k || !k.pub || !k.pvt) return false;\n\t\t\tsessionStorage.setItem(ACTIVE_KEY_STORE, JSON.stringify({ pub: k.pub, pvt: k.pvt }));\n\t\t\treturn true;\n\t\t};\n\t\twindow.clearActiveKey = function() { sessionStorage.removeItem(ACTIVE_KEY_STORE); };\n\t\t// applyActiveKey fills a pub/pvt field pair from the active key and renders a\n\t\t// banner (with a \"Quitar\" link) into bannerId. Used by the signing forms.\n\t\twindow.applyActiveKey = function(pubId, pvtId, bannerId) {\n\t\t\tvar k = getActiveKey();\n\t\t\tvar banner = bannerId ? document.getElementById(bannerId) : null;\n\t\t\tif (!k || !k.pub) { if (banner) banner.innerHTML = ''; return; }\n\t\t\tvar pub = document.getElementById(pubId), pvt = document.getElementById(pvtId);\n\t\t\tif (pub) pub.value = k.pub;\n\t\t\tif (pvt) pvt.value = k.pvt;\n\t\t\tif (banner) {\n\t\t\t\tbanner.innerHTML = '<div class=\"alert alert-info\" style=\"display:flex;justify-content:space-between;align-items:center;gap:12px;\">' +\n\t\t\t\t\t'<span>Firmando como <strong>' + k.pub.slice(0, 14) + '…</strong></span>' +\n\t\t\t\t\t'<a href=\"#\" style=\"font-weight:600;\" onclick=\"clearActiveKey();applyActiveKey(\\'' + pubId + '\\',\\'' + pvtId + '\\',\\'' + bannerId + '\\');return false;\">Quitar</a>' +\n\t\t\t\t\t'</div>';\n\t\t\t}\n\t\t};\n\n\t\t// ===== Shared key helpers (copy / download / render) =====\n\t\tfunction _fallbackCopy(text) {\n\t\t\tvar ta = document.createElement('textarea');\n\t\t\tta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';\n\t\t\tdocument.body.appendChild(ta); ta.focus(); ta.select();\n\t\t\ttry { document.execCommand('copy'); } catch (e) {}\n\t\t\tdocument.body.removeChild(ta);\n\t\t}\n\t\t// copyText reads the .key-display sibling within the button's .key-row and copies it.\n\t\twindow.copyText = function(btn) {\n\t\t\tvar row = btn.closest ? btn.closest('.key-row') : btn.parentElement;\n\t\t\tvar disp = row ? row.querySelector('.key-display') : null;\n\t\t\tvar text = disp ? disp.textContent : '';\n\t\t\tfunction done() {\n\t\t\t\tvar prev = btn.textContent; btn.textContent = 'Copiado'; btn.disabled = true;\n\t\t\t\tsetTimeout(function() { btn.textContent = prev; btn.disabled = false; }, 1200);\n\t\t\t}\n\t\t\tif (navigator.clipboard && navigator.clipboard.writeText) {\n\t\t\t\tnavigator.clipboard.writeText(text).then(done).catch(function() { _fallbackCopy(text); done(); });\n\t\t\t} else { _fallbackCopy(text); done(); }\n\t\t};\n\t\t// downloadJSON triggers a client-side download of obj as a pretty JSON file.\n\t\twindow.downloadJSON = function(filename, obj) {\n\t\t\tvar blob = new Blob([JSON.stringify(obj, null, 2)], { type: 'application/json' });\n\t\t\tvar url = URL.createObjectURL(blob);\n\t\t\tvar a = document.createElement('a');\n\t\t\ta.href = url; a.download = filename;\n\t\t\tdocument.body.appendChild(a); a.click(); document.body.removeChild(a);\n\t\t\tsetTimeout(function() { URL.revokeObjectURL(url); }, 1000);\n\t\t};\n\t\t// keyField returns HTML for a labelled key value with a Copy button.\n\t\twindow.keyField = function(label, value) {\n\t\t\tvar safe = (value == null ? '' : String(value))\n\t\t\t\t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n\t\t\treturn '<div class=\"field\"><label class=\"form-label\">' + label + '</label>' +\n\t\t\t\t'<div class=\"key-row\"><div class=\"key-display\">' + safe + '</div>' +\n\t\t\t\t'<button type=\"button\" class=\"btn btn-outline btn-sm copy-btn\" onclick=\"copyText(this)\">Copiar</button></div></div>';\n\t\t};\n\n\t\t// ---------- formato de fechas (unificado: DD/MM/YYYY) ----------\n\t\t// Fechas puras 'YYYY-MM-DD' se formatean sin conversión de zona horaria\n\t\t// (evita el desfase de un día). Las que llevan hora se localizan.\n\t\twindow.fmtFecha = function(v) {\n\t\t\tif (v == null || v === '') return '—';\n\t\t\tvar s = String(v).trim();\n\t\t\tvar m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(s);\n\t\t\tif (m) return m[3] + '/' + m[2] + '/' + m[1];\n\t\t\tvar d = new Date(s);\n\t\t\tif (isNaN(d.getTime())) return s;\n\t\t\treturn String(d.getDate()).padStart(2, '0') + '/' +\n\t\t\t\tString(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();\n\t\t};\n\t\twindow.fmtFechaHora = function(v) {\n\t\t\tif (v == null || v === '') return '—';\n\t\t\tvar d = new Date(v);\n\t\t\tif (isNaN(d.getTime())) return window.fmtFecha(v);\n\t\t\treturn window.fmtFecha(d) + ', ' +\n\t\t\t\tString(d.getHours()).padStart(2, '0') + ':' +\n\t\t\t\tString(d.getMinutes()).padStart(2, '0');\n\t\t};\n\t\t</script></body></html>")
